import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const parameterBillingItemCodeForAmount = input?.parametros_de_la_regla?.parameter_billingItem_code_for_amount;
  const activeEnergyBillingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
  const consumo = activeEnergyBillingItems.find(item => item.legacy_billing_item_id === parameterBillingItemCodeForAmount);

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode == "null" || billingItemCode == " "  ) {
    return {
      ...input,
        result: {
          rule_description: 'parameter_billingItem_code for rule Alumbrado publico-Porcentaje de importe por rangos de importe not found',
          status: 'ERROR',
        }
    };
  };



  // Fuente ÚNICA: arreglo de rangos
  const prices = Array.isArray(input?.percentage_pricing?.percentages)
    ? input.percentage_pricing.percentages
    : [];

  // Ordena por límite superior ascendente y mapea a {limite, precio}
  const filteredRanges = prices
    .slice()
    .sort(
      (a, b) =>
        Number(a.interval_high ?? 0) -
        Number(b.interval_high ?? 0)
    )
    .map((r) => ({
      limite:
        Number(r.interval_high) === 999999999 ||
        r.interval_high == null
          ? 999999999
          : Number(r.interval_high),
      porcentaje: Number(r.percentage),
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'Rate prices for Alumbrado publico-Porcentaje de importe por rangos de importe not found',
        status: 'ERROR',
      }
    };
  }

  let importe_alumbrado = 0;
  let limite_anterior = 0;
  let i = 0;

  for (; i < filteredRanges.length; i++) {
    const rango = filteredRanges[i];

    if (
      consumo.billing_item_amount >= limite_anterior &&
      consumo.billing_item_amount <= rango.limite &&
      rango.limite !== 999999999
    ) {
      break;
    } else if (
      consumo.billing_item_amount >= limite_anterior &&
      rango.limite === 999999999
    ) {
      break;
    }

    limite_anterior = rango.limite;
  }

  // Fallback si no se encontró (por si el consumo es mayor al último límite finito)
  if (i >= filteredRanges.length) i = filteredRanges.length - 1;

  importe_alumbrado = filteredRanges[i].porcentaje * (consumo.billing_item_amount/100);

  const billingItems = input.tsl_wo_work_order_attribute.billing_items.public_lighting_billing_items;
  const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);

  if (!billingItem) {
    return {
      ...input,
        result: {
          rule_description: 'The parameter_billingItem_code ' + billingItemCode + ' could not be found in the billing concepts structure',
          status: 'ERROR',
        }
    };
  }
  billingItem.billing_item_amount = importe_alumbrado;

  return {
    ...input,
    result: {
      total_amount: importe_alumbrado,
      status: 'OK',
      rule_description:
        'Alumbrado publico-Porcentaje de importe por rangos de importe amount calculation rule completed',
    },
  };
};
